slides.codeSnippet:
h1, h2, h3 {
  font-family: 'Georgia', serif;
  margin-bottom: 0.5em;
}
.btn-primary, .btn-danger {
  padding: 10px 20px;
  border-radius: 4px;
}

/* Only links with class .btn */
a.btn {
  text-decoration: none;
  background: steelblue;
  color: white;
}
/* Only divs with id #special and class .note */
div#special.note {
  border-left: 4px solid gold;
  padding-left: 15px;
}
